```dart
import 'dart:math'; // for calculating averages

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // positive for profit, negative for loss

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

List<String> topThreeCoinsHighestAverageProfit(List<Transaction> transactions) {
  Map<String, List<double>> coinProfits = {};

  // Calculate profits for each coin and store them in a map
  for (var transaction in transactions) {
    if (!coinProfits.containsKey(transaction.coinName)) {
      coinProfits[transaction.coinName] = [0];
    }
    coinProfits[transaction.coinName].add(transaction.profitLoss);
  }

  // Find coins with the highest average profit
  List<MapEntry<String, double>> avgProfits = coinProfits.entries.map((entry) {
    double avgProfit = entry.value.reduce((a, b) => a + b) / entry.value.length;
    return MapEntry(entry.key, avgProfit);
  }).toList();

  // Sort the coins by their average profit and get the top three
  avgProfits.sort((a, b) => b.value.compareTo(a.value));
  return List<String>.generate(3, (index) => avgProfits[index].key);
}

