export const CreateObjectView = observer(({ model }: { model: CreateObjectModel }) => {
 return (
 <div id="CreateObjectView">
   <label htmlFor="assetInput">Asset:</label>
   <input type="text" id="assetInput" value={model.selectedAssetId} onChange={(e) => model.setSelectedAsset(e.target.value)}>
   <button onClick={() => {
     if (model.selectedAssetId && model.availableAssets.some(({ id }) => id === model.selectedAssetId)) {
       model.createObject(model.selectedAssetId).then();
       model.setSelectedAsset(null);
     }
   }}>Add Object</button>
   <Select id="assetSelect" value={model.selectedAssetId} onChange={(e) => model.setSelectedAsset(e.target.value)}>
     {model.availableAssets.map((asset) => (
       <option key={asset.id} value={asset.id}>
         {asset.name}
