func generateStatement(userInteractions: [String: Int], colorPreferences: String?, reviews: [Review]) -> String {
    var statement = ""

    if userInteractions.count > 0 {
        statement += "Based on your \(userInteractions.count) clicks on \(userInteractions.keys.joined(separator: ", ")), "

        if let colorPref = colorPreferences {
            statement += "and color preference for \(colorPref), "
        }

        statement += "we recommend the following products:"

        for review in reviews {
            statement += "\n\n- \(review.title): \(review.rating) stars - \(review.text)"
        }
    } else {
        statement += "We couldn't find enough information about your preferences. Please explore our offerings and click on products that interest you."
    }

    return statement
}

