using System;
using System.Net.Http;
using System.Threading.Tasks;

public class RestServiceWrapper<T> where T : new()
{
    private readonly string _baseUrl;
    private readonly HttpClient _httpClient;
    private string _accessToken;

    public RestServiceWrapper(string baseUrl)
    {
        _baseUrl = baseUrl;
        _httpClient = new HttpClient();
    }

    public void SetAccessToken(string token)
    {
        _accessToken = token;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _accessToken);
    }

    public async Task<T> GetAsync(string endpoint)
    {
        using var response = await _httpClient.GetAsync($"{_baseUrl}/{endpoint}");
        if (!response.IsSuccessStatusCode)
            throw new Exception($"Error getting data from server: Status Code = {response.StatusCode}");

        var contentString = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(contentString);
    }

    public async Task<T> PostAsync(string endpoint, object requestData)
    {
        string json = JsonConvert.SerializeObject(requestData);
        using var request = new StringContent(json, System.Text.Encoding.UTF8, "application/json");

        using var response = await _httpClient.PostAsync($"{_baseUrl}/{endpoint}", request);
        if (!response.IsSuccessStatusCode)
            throw new Exception($"Error posting data to server: Status Code = {response.StatusCode}");

        var contentString = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<T>(contentString);
    }

    // Implement Put and Delete methods as needed
}
```

