function determineProtocol(inputData) {
  let ipVersion;
  if (/^([0-9a-f:]{15}|[0-9]{1,3}\.[0-9]{1,3}(\.:[0-9]{1,3}){3})$/.test(inputData.sourceIP) && /^([0-9a-f:]{15}|[0-9]{1,3}\.(0-9){1,3}(\.:[0-9]{1,3}){3})$/.test(inputData.destinationIP)) { // check if both source and destination IPs are valid IP addresses
    ipVersion = inputData.sourceIP.split(":")[0].split(".").length === 4 ? IPv4 : IPv6; // determine IP version based on the number of dots in the source IP address
  }
  const protocol;
  switch (ipVersion) {
    case IPv6:
      if (inputData.port === 80) {
        protocol = HTTP; // HTTP over IPv6
      } else if (inputData.protocol === undefined) {
        protocol = UDP; // no specific protocol specified, default to UDP
      }
      break;
    case IPv4:
      protocol = inputData.port === 80 ? HTTP : UDP; // default to HTTP for port 80, otherwise UDP
      break;
    default:
      throw new Error("Invalid IP version");
  }
  return protocol;
}
