 To create a decorator for Nest.js middleware that checks the `NODE_ENV` variable and behaves accordingly, follow these steps:

First, let's create a custom decorator named `CheckNodeEnv`. This decorator will use Reflector to store the expected Node.js environment (e.g., "production" or "development") as a metadata property on the targeted controller or middleware function.

Create a new file `check-node-env.decorator.ts` with the following content:

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { Reflector } from '@nestjs/core';

export const CHECK_NODE_ENV = 'checkNodeEnv';

export const CheckNodeEnv = (expectedEnvironment: string): Function => {
  return (target: Object, key: string | symbol, desc: PropertyDescriptor) => {
    Reflector.create(target).setMetadata(CHECK_NODE_ENV, { expectedEnvironment });
  };
};

export const GetNodeEnv = createParamDecorator((data: unknown, ctx: ExecutionContext) => {
  const reflector = Reflector.create(ctx.getHandler());
  return reflector.getMetadata(CHECK_NODE_ENV, ctx.getHandler())?.expectedEnvironment;
});

export function NodeEnvMiddleware() {
  return function (req: Request, res: Response, next: NextFunction) {
    if (process.env.NODE_ENV === GetNodeEnv() || process.env.NODE_ENV === 'test') {
      next();
    } else {
      res.status(403).send(false);
    }
  };
}
```

Now you can apply this decorator to your controllers or middleware functions like this:

```typescript
import { Controller, Get, UseGuards, MiddlewaresConsumer, Module, NestFactory } from '@nestjs/core';
import { ApplicationModule } from './application.module';
import { CheckNodeEnv } from './check-node-env.decorator';
import * as bodyParser from 'body-parser';
import * as helmet from 'helmet';
import * as compression from 'compression';

