```typescript
import React, { useState } from 'react';
import { useCombobox } from 'downshift';
import AutoSuggestions from './AutoSuggestions';

interface EmailOption {
  value: string;
  label: string;
}

const searchEmails = async (prefix: string): Promise<EmailOption[]> => {
  // Call your API or perform local search here
  const response = await fetch(`/api/searchEmails?prefix=${prefix}`);
  const data = await response.json();
  return data.map((email: any) => ({ value: email, label: email }));
};

const EmailInput: React.FC = () => {
  const [inputItems, setInputItems] = useState<EmailOption[]>([]);
  const { isOpen, getMenuProps, getInputProps, highlightedIndex, getComboboxProps } = useCombobox({ items: inputItems, onInputValueChange: async ({ inputValue }) => setInputItems(await searchEmails(inputValue)) });

  return (
    <div>
      <input {...getInputProps()} placeholder="Enter email address" />
      <button onClick={() => isOpen && getMenuProps().toggleMenu()}>X</button>
      <ul {...getMenuProps()}>
        {isOpen && (
          <AutoSuggestions
            items={inputItems}
            itemToString={item => item.label}
            highlightedIndex={highlightedIndex}
            getItemProps={getMenuItemProps => item => ({
              ...getItemProps(),
              style: { backgroundColor: highlightedIndex === item.index ? '#ddd' : 'transparent', cursor: 'pointer' },
            })}
          />
        )}
      </ul>
    </div>
  );
};

export default EmailInput

