CREATE PROCEDURE dbo.ConvertCelsiusToFahrenheit (@Celsius DECIMAL(5, 2))
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate input parameter
    IF @Celsius IS NULL OR @Celsius < -273.15 -- minimum temperature in Celsius
